  "help.fastfood.1": "Anywhere: 📍 Places → 📱 Your phone → 🛵 ChopNow delivery (e cost pass and e dey take like 40 minutes).",
  "help.fastfood.2": "Fast food dey quick and e dey full belle, but to cook for house na the cheapest way to chop.",
  "help.feedback.q": "How I go send feedback?",
  "help.feedback.0": "Tap 💬 Feedback for the right side of the screen (or 👤 Me → Send feedback).",
  "help.feedback.1": "Pick Bug, Idea, E confuse me or I like…, give star rating if you want, and write your message.",
  "help.feedback.2": "Tap Send. If you no dey online, e go keep am and send am next time.",
  "help.language.q": "How I go change language?",
  "help.language.0": "Tap 👤 Me → Language and pick English, Deutsch or Naija Pidgin.",
  "help.language.1": "You fit also choose am for the first screen when you start new life.",
  "help.diary.q": "Where I go see wetin happen before?",
  "help.diary.0": "Tap 👤 Me → Open your diary. Every event dey save there, day by day, and you fit search am.",
  "help.diary.1": "Your lives wey don finish dey under 👻 Past lives.",
  "help.lede": "Tap question to see how, step by step.",
  "help.plan": "How to pass one day",
  "help.guide": "📖 Show the full beginner guide",
  "guide.counter": "How to play · {n} of {total}",
  "guide.skip": "Skip",
  "guide.back": "‹ Back",
  "guide.next": "Next ›",
  "guide.go": "Make we go! 🚀",
  "guide.welcome": "Welcome to Lagos!",
  "guide.welcome.0": "You just land with **₦10,000** and one small room for Mushin.",
  "guide.welcome.1": "Your aim: hustle your way go up, then **japa abroad** or **buy your own flat**.",
  "guide.welcome.2": "This short guide go show you how everything dey work. You fit open am again anytime with the **❓ Help** button for right side.",
  "guide.screen": "Your world full the screen",
  "guide.screen.0": "Your flat dey for middle. **Tap any furniture** to use am (bed, burner, bucket, toilet…). Tap the floor to waka. Drag to turn the view; pinch or scroll to zoom.",
  "guide.screen.1": "**Top bar**: your name, the day and time, where you dey, days wey remain for rent, and your **₦ money**.",
  "guide.screen.2": "Time dey run by itself. E dey wait when panel open.",
  "guide.screen.3": "**For right side**: ❓ Help, 💬 Feedback, ❚❚ Pause, 🎥 View (from top or first person) and Speed (1×, 2×, 4×).",
  "guide.screen.4": "**❤️ Health** dey drop when needs empty. **😄 Mood** wey reach 70+ go make shifts pay 10% more. **💡** light dey, **🕯️** NEPA don take light.",
  "guide.needs": "Your six needs",
  "guide.needs.intro": "The small bars for the top bar na your needs. Keep them high. Bar go turn red and dey blink when e low.",
  "guide.needs.0": "🍲 **Hunger**: cook for house, chop for buka, or buy fast food",
  "guide.needs.1": "⚡ **Energy**: sleep for your mattress",
  "guide.needs.2": "🎉 **Enjoyment**: TV, ball, beach",
  "guide.needs.3": "💬 **Friends**: gist with your guys, call Mummy",
  "guide.needs.4": "🛁 **Clean body**: bucket bath or shower",
  "guide.needs.5": "🚻 **Toilet**: use toilet",
  "guide.buttons": "The buttons for down",
  "guide.buttons.intro": "Each one dey open panel on top your world. Close am with ✕ to go back to the game.",
  "guide.buttons.0": "**📍 Places**: everything wey you fit do where you dey: chop, hustle, train skills, enjoy.",
  "guide.buttons.1": "**🚌 Travel**: go another part of Lagos with danfo, keke or okada.",
  "guide.buttons.2": "**💼 Jobs**: apply for work. Promotion go raise your pay.",
  "guide.buttons.3": "**🛒 Shop**: buy furniture for your room. Every one dey open new things to do.",
  "guide.buttons.4": "**✈️ Goals**: your big dream: japa abroad, or buy your own flat.",
  "guide.buttons.5": "**👤 Me**: your skills and moods, language, diary, account and save files.",
  "guide.buttons.6": "**🚶🏾 Walk outside**: waka the 3D streets and enter any building.",
  "guide.buttons.7": "**💼 Go to work** go show when you dey near your work.",
  "guide.missions": "Follow the missions 🎯",
  "guide.missions.0": "The **🎯 Mission** card (top left) dey tell you wetin to do next. Tap **How?** to see every step, one by one.",
  "guide.missions.1": "**👉 Show me** go carry you go there straight. Look for the 🎯 tag: e dey mark the button and place wey you need.",
  "guide.missions.2": "Every mission get reward. The **💡 Tip** bubble for down dey give you hints as you dey play, and e dey warn you when one need don low.",
  "guide.tags": "Wetin the tags mean",
  "guide.tags.intro": "Small tags for buttons dey explain them quick quick:",
  "guide.tags.grey": "Grey buttons no fit work yet: the red line under them dey talk why.",
  "guide.feedback": "Tell us wetin you think 💬",
  "guide.feedback.0": "Tap **💬 Feedback** for the right side of the screen anytime to send us message.",
  "guide.feedback.1": "Pick **🐞 Bug**, **💡 Idea**, **😕 E confuse me** or **❤️ I like…**, add star rating if you want, and write small. We dey read every message.",
  "guide.feedback.2": "Everything wey happen dey save for your **📖 diary** (👤 Me), and you fit change the **language** there too.",
