  "event.cousin.title": "Family call",
  "event.cousin.text": "Your cousin call: \"Abeg, send me ₦2,000 for school fees.\"",
  "event.cousin.c0": "Send ₦2,000",
  "event.cousin.c0.result": "Your cousin happy well well. Family na family.",
  "event.cousin.c1": "Pretend say network bad",
  "event.cousin.c1.result": "You cut the call. Your mind no rest small.",
  "event.mum.title": "Mama for the line",
  "event.mum.text": "Your mama call to pray for you and ask when you go come house.",
  "event.mum.c0": "Send her ₦5,000 for foodstuff",
  "event.mum.c0.result": "She pray for you for ten full minutes. You feel blessed.",
  "event.mum.c1": "Just talk small (30 min)",
  "event.mum.c1.result": "Her voice make you smile.",
  "event.nepa-bill.title": "Estimated bill",
  "event.nepa-bill.text": "NEPA man dey gate with \"estimated\" bill for light wey you no even see.",
  "event.nepa-bill.c0": "Just pay ₦3,000",
  "event.nepa-bill.c0.result": "E waka dey smile. You no dey smile.",
  "event.nepa-bill.c1": "Argue am down",
  "event.nepa-bill.c1.result": "E no gree shift and e call you stubborn. Your evening don spoil.",
  "event.nepa-bill.c1.win": "You talk am down reach zero. Neighbours clap for you.",
  "event.landlord-levy.title": "Landlord wahala",
  "event.landlord-levy.text": "Your landlord knock: \"Everybody must pay ₦3,000 development levy.\"",
  "event.landlord-levy.c0": "Pay ₦3,000",
  "event.landlord-levy.c0.result": "E nod head and waka. Peace for now.",
  "event.landlord-levy.c1": "Argue with am (30 min)",
  "event.landlord-levy.c1.result": "E grumble but e leave am… this time.",
  "event.found-money.title": "Lucky find",
  "event.found-money.text": "You see ₦1,000 note for ground.",
  "event.found-money.c0": "Put am for pocket",
  "event.found-money.c0.result": "Na your lucky day!",
  "event.found-money.c1": "Give am to the mallam wey dey near",
  "event.found-money.c1.result": "E bless you. You feel good.",
  "event.agbero.title": "Agbero!",
  "event.agbero.text": "Agbero block your road: \"Owo da? Pay your levy!\"",
  "event.agbero.c0": "Pay ₦500",
  "event.agbero.c0.result": "E wave you make you pass.",
  "event.agbero.c1": "Argue with am (30 min)",
  "event.agbero.c1.result": "After thirty minutes of shouting, you escape. E tire you.",
  "event.checkpoint.title": "Checkpoint",
  "event.checkpoint.text": "Police for checkpoint: \"Where your papers? Wetin you carry?\"",
  "event.checkpoint.c0": "\"Find something for the boys\" (₦1,000)",
  "event.checkpoint.c0.result": "Dem wave you make you go.",
  "event.checkpoint.c1": "Calm down and show your ID (40 min)",
  "event.checkpoint.c1.result": "After long talk, dem let you go.",
  "event.rain.title": "Heavy rain",
  "event.rain.text": "Sky don open. Road dey flood.",
  "event.rain.c0": "Wait under shed (2 h)",
  "event.rain.c0.result": "Rain don finally stop.",
  "event.rain.c1": "Waka pass the flood",
  "event.rain.c1.result": "You reach, but you don soak and dirty.",
  "event.fuel.title": "Fuel scarcity",
  "event.fuel.text": "Fuel no dey anywhere. Your neighbour dey sell black-market petrol for your gen.",
  "event.fuel.c0": "Buy from am (₦3,000)",
  "event.fuel.c0.result": "E cost, but your phone still get charge.",
  "event.fuel.c1": "Join queue for filling station (3 h)",
  "event.fuel.c1.result": "After three hours, you finally buy fuel for normal price.",
  "event.phone.title": "Cracked screen",
  "event.phone.text": "Your phone slip and the screen crack.",
  "event.phone.c0": "Fix am for computer village (₦8,000)",
  "event.phone.c0.result": "E don be like new.",
  "event.phone.c1": "Manage am like that",
  "event.phone.c1.result": "Every message now dey look like spider web.",
  "event.investment.title": "Business proposal",
  "event.investment.text": "Your guy Tunde want ₦10,000 for him new shawarma stand. \"I go pay you back double!\"",
  "event.investment.c0": "Invest ₦10,000",
  "event.investment.c0.result": "The stand close after one week. Your money don waka.",
  "event.investment.c0.win": "The shawarma hit! Tunde pay you ₦22,000.",
  "event.investment.c1": "Politely say no",
  "event.investment.c1.result": "Tunde vex small but e understand.",
  "event.remote-gig.title": "DM from recruiter",
  "event.remote-gig.text": "Recruiter offer you quick remote gig: fix one website before tonight.",
  "event.remote-gig.c0": "Take am (4 h)",
  "event.remote-gig.c0.result": "You no fit fix the bug in time. No pay, na only stress.",
  "event.remote-gig.c0.win": "Client happy! ₦15,000 don land for your account.",
  "event.remote-gig.c1": "Ignore am",
  "event.remote-gig.c1.result": "Maybe next time.",
  "event.owambe.title": "Owambe invitation",
  "event.owambe.text": "Somebody invite you to owambe party wey dey near!",
  "event.owambe.c0": "Go dance (3 h)",
  "event.owambe.c0.result": "Jollof, music and new friends. Which kind night be this!",
  "event.owambe.c1": "Politely say no",
  "event.owambe.c1.result": "Maybe next time.",
