  "event.match.text": "Super Eagles dey play. Viewing centre don full.",
  "event.match.c0": "Watch with the crowd (₦300, 2 h)",
  "event.match.c0.result": "GOAL! The whole street shout together.",
  "event.match.c1": "Leave am",
  "event.match.c1.result": "You dey hear the shout from far.",
  "mission.bath.title": "Freshen up",
  "mission.bath.goal": "Do bucket bath for house.",
  "mission.bath.step0": "Dey your house for Mushin: your flat go full the screen.",
  "mission.bath.step1": "Tap the blue bucket for bathroom (top right of the flat). Or tap 👉 Show me.",
  "mission.bath.step2": "Tap 🪣 Bucket bath.",
  "mission.cook.title": "Cook your first food",
  "mission.cook.goal": "Cook egusi for your gas burner.",
  "mission.cook.step0": "For house, tap the gas burner for kitchen (top left of the flat). Or tap 👉 Show me.",
  "mission.cook.step1": "Tap 🍳 Cook egusi. E go use 1 food pack (you start with 3).",
  "mission.first-naira.title": "Make your first naira",
  "mission.first-naira.goal": "Make money from side hustle.",
  "mission.first-naira.step0": "Tap 📍 Places for the bottom of the screen.",
  "mission.first-naira.step1": "Scroll go down reach 📱 Your phone.",
  "mission.first-naira.step2": "Tap 💬 WhatsApp hustle. Buttons wey dey pay money get 💰 tag.",
  "mission.groceries.title": "Fill the kitchen",
  "mission.groceries.goal": "Buy groceries so that you fit continue to cook.",
  "mission.groceries.step0": "Tap 📍 Places for down.",
  "mission.groceries.step1": "Find 🧺 Oja Tuntun Market (e dey open 06:00–19:00).",
  "mission.groceries.step2": "Tap 🧺 Buy groceries. Time don go? Order delivery from 📱 Your phone instead (e cost pass).",
  "mission.job.title": "Get work",
  "mission.job.goal": "Apply for any work.",
  "mission.job.step0": "Tap 💼 Jobs for down.",
  "mission.job.step1": "Pick work wey no get 🔒. POS business na the easiest to start.",
  "mission.job.step2": "Tap Apply.",
  "mission.ride.title": "Enter ride",
  "mission.ride.goal": "Travel go another part of Lagos.",
  "mission.ride.step0": "Tap 🚌 Travel for down.",
  "mission.ride.step1": "Pick where you wan go. POS and okada work dey for Yaba.",
  "mission.ride.step2": "Tap ride: 🚌 Danfo cheap, 🏍️ Okada fast, 🚶 Trek free but e slow.",
  "mission.shift.title": "Work your first shift",
  "mission.shift.goal": "Go your work and work one shift.",
  "mission.shift.step0": "Tap 💼 Jobs to see where your work dey.",
  "mission.shift.step1": "Go there with 🚌 Travel if you never reach.",
  "mission.shift.step2": "Tap the big 💼 Go to work button. You need ⚡ Energy wey pass 15, so sleep first if you don tire.",
  "mission.streets.title": "Waka the streets",
  "mission.streets.goal": "Waka round town for 3D and enter one place.",
  "mission.streets.step0": "Tap the 🚶🏾 Walk outside button (bottom right).",
  "mission.streets.step1": "Waka with the thumbstick or arrow keys, or just tap building. 📍 Where you dey go? go waka you reach there.",
  "mission.streets.step2": "For door, tap 🚪 Enter…",
  "mission.skill.title": "Learn skill",
  "mission.skill.goal": "Reach level 1 for any skill.",
  "mission.skill.step0": "Tap 📍 Places and look for the 📈 tag: those actions dey train skill.",
  "mission.skill.step1": "Better ones to start: 📖 Read book for library (Yaba), 🏃🏾 Jog round the park (Mushin), 🍲 Help for kitchen (Buka).",
  "mission.skill.step2": "Check your levels for 👤 Me.",
  "mission.furniture.title": "Make am feel like home",
  "mission.furniture.goal": "Buy one furniture.",
  "mission.furniture.step0": "Dey your house for Mushin and tap 🛒 Shop for down.",
  "mission.furniture.step1": "Pick something. 📻 Radio (₦8,000) cheap.",
  "mission.furniture.step2": "Tap the floor where you wan put am, then tap Buy.",
  "mission.rent.title": "Pay your rent",
  "mission.rent.goal": "Get ₦15,000 ready when rent day reach.",
  "mission.rent.step0": "The top bar dey show \"rent in X days\". Rent go comot by itself for rent day.",
  "mission.rent.step1": "Keep at least ₦15,000 before then. Work and hustle to get am.",
  "mission.rent.step2": "Money no complete? You go owe landlord. Tap Pay for the red bar to clear am, or dem go pursue you next rent day.",
  "mission.promotion.title": "Get promotion",
  "mission.promotion.goal": "Collect your first promotion.",
  "mission.promotion.step0": "Tap 💼 Jobs to see wetin your next promotion need: number of shifts and skill level.",
  "mission.promotion.step1": "Continue to work shifts.",
  "mission.promotion.step2": "Train the skill wey e ask for (look for 📈 for 📍 Places).",
  "mission.generator.title": "Beat NEPA",
  "mission.generator.goal": "Get your own gen so that when light go, e no go stop you.",
  "mission.generator.step0": "Save ₦120,000.",
  "mission.generator.step1": "For house, tap 🛒 Shop → ⚡ Small generator.",
  "mission.generator.step2": "Buy fuel: 📍 Places → 📱 Your phone → ⛽ Buy generator fuel.",
  "mission.savings.title": "Save ₦300,000",
  "mission.savings.goal": "Gather money for your big dream.",
  "mission.savings.step0": "Work shifts and side hustle, and spend with sense.",
  "mission.savings.step1": "Better work dey pay well well: check 💼 Jobs for wetin dem need.",
  "mission.savings.step2": "Tap ✈️ Goals to see how much your dream go cost.",
